"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { Button } from "./button";
import "./styles/cstrike.css";

interface BuyMenuItem {
  key: string;
  name: string;
  price: number;
  team?: "ct" | "t" | "both";
}

interface BuyMenuCategory {
  key: string;
  label: string;
  items: BuyMenuItem[];
}

interface BuyMenuProps extends React.HTMLAttributes<HTMLDivElement> {
  categories: BuyMenuCategory[];
  money?: number;
  onBuy?: (item: BuyMenuItem) => void;
  team?: "ct" | "t";
}

const DEFAULT_CATEGORIES: BuyMenuCategory[] = [
  {
    key: "1",
    label: "Pistols",
    items: [
      { key: "1", name: "USP", price: 500, team: "ct" },
      { key: "2", name: "Glock-18", price: 400, team: "t" },
      { key: "3", name: "Desert Eagle", price: 650, team: "both" },
      { key: "4", name: "P228", price: 600, team: "both" },
      { key: "5", name: "Dual Elites", price: 800, team: "t" },
      { key: "6", name: "Five-SeveN", price: 750, team: "ct" },
    ],
  },
  {
    key: "2",
    label: "Shotguns",
    items: [
      { key: "1", name: "M3 Super 90", price: 1700, team: "both" },
      { key: "2", name: "XM1014", price: 3000, team: "both" },
    ],
  },
  {
    key: "3",
    label: "SMGs",
    items: [
      { key: "1", name: "MP5 Navy", price: 1500, team: "both" },
      { key: "2", name: "TMP", price: 1250, team: "ct" },
      { key: "3", name: "P90", price: 2350, team: "both" },
      { key: "4", name: "MAC-10", price: 1400, team: "t" },
      { key: "5", name: "UMP-45", price: 1700, team: "both" },
    ],
  },
  {
    key: "4",
    label: "Rifles",
    items: [
      { key: "1", name: "AK-47", price: 2500, team: "t" },
      { key: "2", name: "SG 552", price: 3500, team: "t" },
      { key: "3", name: "M4A1", price: 3100, team: "ct" },
      { key: "4", name: "AUG", price: 3500, team: "ct" },
      { key: "5", name: "Scout", price: 2750, team: "both" },
      { key: "6", name: "AWP", price: 4750, team: "both" },
      { key: "7", name: "G3SG1", price: 5000, team: "t" },
      { key: "8", name: "SG 550", price: 4200, team: "ct" },
    ],
  },
  {
    key: "5",
    label: "Machine Guns",
    items: [
      { key: "1", name: "M249", price: 5750, team: "both" },
    ],
  },
  {
    key: "8",
    label: "Equipment",
    items: [
      { key: "1", name: "Kevlar Vest", price: 650, team: "both" },
      { key: "2", name: "Kevlar + Helmet", price: 1000, team: "both" },
      { key: "3", name: "Flashbang", price: 200, team: "both" },
      { key: "4", name: "HE Grenade", price: 300, team: "both" },
      { key: "5", name: "Smoke Grenade", price: 300, team: "both" },
      { key: "6", name: "Defuse Kit", price: 200, team: "ct" },
      { key: "7", name: "Night Vision", price: 1250, team: "both" },
    ],
  },
];

const BuyMenu = React.forwardRef<HTMLDivElement, BuyMenuProps>(
  (
    {
      className,
      categories = DEFAULT_CATEGORIES,
      money = 800,
      onBuy,
      team = "ct",
      ...props
    },
    ref
  ) => {
    const [selectedCategory, setSelectedCategory] = React.useState<string | null>(null);

    const currentCategory = categories.find((c) => c.key === selectedCategory);
    const filteredItems = currentCategory?.items.filter(
      (item) => item.team === "both" || item.team === team
    );

    return (
      <div
        ref={ref}
        className={cn(
          "w-full max-w-lg bg-[var(--cs-bg)]/95 backdrop-blur-sm",
          "border-2 border-t-[var(--cs-border-light)] border-l-[var(--cs-border-light)]",
          "border-b-[var(--cs-border-dark)] border-r-[var(--cs-border-dark)]",
          className
        )}
        {...props}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-2 bg-[var(--cs-bg-secondary)] border-b-2 border-b-[var(--cs-border-dark)]">
          <span className="cs-font-ui text-sm text-[var(--cs-text-title)] cs-text-shadow">
            Buy Menu
          </span>
          <span className="cs-font-hud text-sm cs-hud-glow-green">
            ${money.toLocaleString()}
          </span>
        </div>

        <div className="flex min-h-[300px]">
          {/* Categories */}
          <div className="w-40 border-r-2 border-r-[var(--cs-border-dark)] bg-[var(--cs-bg-secondary)] p-2">
            {categories.map((cat) => (
              <Button
                key={cat.key}
                variant="menu"
                size="sm"
                className={cn(
                  "w-full mb-0.5 px-2",
                  selectedCategory === cat.key && "text-white bg-[var(--cs-bg-selection)]"
                )}
                onClick={() => setSelectedCategory(cat.key)}
              >
                <span className="text-[var(--cs-text-dim)] mr-2 text-[10px]">
                  {cat.key}.
                </span>
                {cat.label}
              </Button>
            ))}
          </div>

          {/* Items */}
          <div className="flex-1 p-2">
            {filteredItems ? (
              filteredItems.map((item) => {
                const canAfford = money >= item.price;
                return (
                  <Button
                    key={item.key}
                    variant="buy"
                    size="sm"
                    className={cn(
                      "w-full mb-1 justify-between px-3",
                      !canAfford && "opacity-40"
                    )}
                    disabled={!canAfford}
                    onClick={() => onBuy?.(item)}
                  >
                    <span className="flex items-center gap-2">
                      <span className="text-[var(--cs-text-dim)] text-[10px]">
                        {item.key}.
                      </span>
                      <span>{item.name}</span>
                    </span>
                    <span
                      className={cn(
                        "text-[10px]",
                        canAfford
                          ? "text-[var(--cs-hud-green)]"
                          : "text-[var(--cs-hud-red)]"
                      )}
                    >
                      ${item.price}
                    </span>
                  </Button>
                );
              })
            ) : (
              <div className="flex h-full items-center justify-center">
                <span className="cs-font-ui text-xs text-[var(--cs-text-dim)] cs-text-shadow">
                  Select a category
                </span>
              </div>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="px-4 py-2 bg-[var(--cs-bg-secondary)] border-t-2 border-t-[var(--cs-border-dark)]">
          <span className="cs-font-ui text-[10px] text-[var(--cs-text-dim)]">
            Press [B] to open • Number keys to select
          </span>
        </div>
      </div>
    );
  }
);
BuyMenu.displayName = "BuyMenu";

export { BuyMenu, DEFAULT_CATEGORIES, type BuyMenuCategory, type BuyMenuItem, type BuyMenuProps };

"use client";

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import "./styles/cstrike.css";

const buttonVariants = cva(
  [
    "cs-font-ui cs-text-shadow inline-flex items-center justify-center",
    "cursor-pointer select-none whitespace-nowrap",
    "transition-none",
    "disabled:pointer-events-none disabled:opacity-50",
  ].join(" "),
  {
    variants: {
      variant: {
        default: [
          "bg-[var(--cs-bg)] text-[var(--cs-text-control)]",
          "border-2 border-t-[var(--cs-border-light)] border-l-[var(--cs-border-light)]",
          "border-b-[var(--cs-border-dark)] border-r-[var(--cs-border-dark)]",
          "hover:text-[var(--cs-text-menu-hover)]",
          "active:border-t-[var(--cs-border-dark)] active:border-l-[var(--cs-border-dark)]",
          "active:border-b-[var(--cs-border-light)] active:border-r-[var(--cs-border-light)]",
          "active:text-[var(--cs-text-menu-active)]",
        ].join(" "),
        menu: [
          "bg-transparent text-[var(--cs-text-menu)] border-none",
          "hover:text-[var(--cs-text-menu-hover)]",
          "active:text-[var(--cs-text-menu-active)]",
          "justify-start",
        ].join(" "),
        buy: [
          "bg-[var(--cs-bg-secondary)] text-[var(--cs-text-control)]",
          "border-2 border-t-[var(--cs-border-light)] border-l-[var(--cs-border-light)]",
          "border-b-[var(--cs-border-dark)] border-r-[var(--cs-border-dark)]",
          "hover:bg-[var(--cs-bg)] hover:text-[var(--cs-text-bright)]",
          "active:border-t-[var(--cs-border-dark)] active:border-l-[var(--cs-border-dark)]",
          "active:border-b-[var(--cs-border-light)] active:border-r-[var(--cs-border-light)]",
        ].join(" "),
        hud: [
          "bg-transparent text-[var(--cs-hud-amber)] border-none",
          "cs-hud-glow",
          "hover:brightness-125",
          "active:brightness-75",
        ].join(" "),
        destructive: [
          "bg-[#3a1a1a] text-[var(--cs-team-t)]",
          "border-2 border-t-[#663333] border-l-[#663333]",
          "border-b-[#1a0a0a] border-r-[#1a0a0a]",
          "hover:text-white",
          "active:border-t-[#1a0a0a] active:border-l-[#1a0a0a]",
          "active:border-b-[#663333] active:border-r-[#663333]",
        ].join(" "),
      },
      size: {
        default: "h-9 px-4 py-2 text-sm",
        sm: "h-7 px-3 py-1 text-xs",
        lg: "h-11 px-6 py-3 text-base",
        icon: "h-9 w-9 p-0",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
      <Comp
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };

/* Counter-Strike 1.6 Design System */

/* CS 1.6 Logo Font - "Counter-Strike" by SoJa (free, public domain) */
@font-face {
  font-family: "Counter-Strike";
  src: url("/fonts/counter-strike.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* ===== CS 1.6 VGUI Color System ===== */
:root {
  /* Primary olive-green backgrounds */
  --cs-bg: #4a5942;
  --cs-bg-secondary: #3e4637;
  --cs-bg-dark: #333433;
  --cs-bg-darker: #292929;
  --cs-bg-darkest: #1a1a1a;
  --cs-bg-control: #1a1a1a;
  --cs-bg-selection: #282e22;
  --cs-bg-list: #292929;

  /* Text colors */
  --cs-text: #dedfd6;
  --cs-text-secondary: #a0aa95;
  --cs-text-dim: #75806f;
  --cs-text-disabled: #282e22;
  --cs-text-control: #fffac1;
  --cs-text-bright: #ffc000;
  --cs-text-title: #ffde00;
  --cs-text-menu: #ffcc00;
  --cs-text-menu-hover: #ffffff;
  --cs-text-menu-active: #c0ba50;

  /* Accent colors */
  --cs-accent: #c4b550;
  --cs-accent-secondary: #958831;

  /* Border colors (3D bevel system) */
  --cs-border-light: #8c9284;
  --cs-border-dark: #292c21;
  --cs-border-outline: #000000;

  /* HUD colors (from GoldSrc engine hud.h) */
  --cs-hud-amber: #ffa000;
  --cs-hud-red: #ff1010;
  --cs-hud-green: #00a000;

  /* Team colors */
  --cs-team-ct: #99ccff;
  --cs-team-t: #ff4040;
  --cs-team-neutral: #cccccc;

  /* Slider/scrollbar */
  --cs-slider: #7f8c7f;
  --cs-slider-bg: #1f1f1f;
  --cs-scrollbar-track: #5a6a50;
}

/* ===== Font Classes ===== */
.cs-font-logo {
  font-family: "Counter-Strike", "Impact", sans-serif;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.cs-font-ui {
  font-family: "Verdana", "DejaVu Sans", system-ui, sans-serif;
  font-weight: 600;
  line-height: 1.5;
}

.cs-font-hud {
  font-family: "Courier New", "Courier", monospace;
  font-weight: 700;
  letter-spacing: 1px;
}

.cs-font-console {
  font-family: "Tahoma", "Geneva", sans-serif;
  font-size: 13px;
  line-height: 1.4;
}

/* ===== 3D Beveled Borders ===== */
.cs-bevel-raised {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-light);
  border-left-color: var(--cs-border-light);
  border-bottom-color: var(--cs-border-dark);
  border-right-color: var(--cs-border-dark);
}

.cs-bevel-inset {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-dark);
  border-left-color: var(--cs-border-dark);
  border-bottom-color: var(--cs-border-light);
  border-right-color: var(--cs-border-light);
}

/* ===== HUD Glow Effect ===== */
.cs-hud-glow {
  color: var(--cs-hud-amber);
  text-shadow:
    0 0 8px rgba(255, 160, 0, 0.6),
    0 0 16px rgba(255, 160, 0, 0.3);
}

.cs-hud-glow-red {
  color: var(--cs-hud-red);
  text-shadow:
    0 0 8px rgba(255, 16, 16, 0.6),
    0 0 16px rgba(255, 16, 16, 0.3);
}

.cs-hud-glow-green {
  color: var(--cs-hud-green);
  text-shadow:
    0 0 8px rgba(0, 160, 0, 0.6),
    0 0 16px rgba(0, 160, 0, 0.3);
}

/* ===== Text Shadow (VGUI style) ===== */
.cs-text-shadow {
  text-shadow: 1px 1px 0px rgba(0, 0, 0, 0.8);
}

/* ===== Panel Backgrounds ===== */
.cs-panel {
  background-color: var(--cs-bg);
}

.cs-panel-dark {
  background-color: var(--cs-bg-dark);
}

.cs-panel-control {
  background-color: var(--cs-bg-control);
}
